\begin{axis}[
%axis on top=true,
tick style={draw=none},
x tick label style={font=\scriptsize},
y tick label style={font=\scriptsize, xshift=2pt, yshift=4pt},
label style={font=\small},
tick style={draw=black, thick},
minor tick style={draw=none},
